from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class Momentum3to6Months(Strategy):
    rationale = (
        "This strategy exploits the tendency for stocks that have performed well over a recent "
        "period (3-6 months) to continue outperforming in the near future. It ranks stocks based "
        "on their short-term returns and allocates capital accordingly."
    )

    def __init__(self, window: int = 180, top_n: int = 20) -> None:
        self._window = window
        self._top_n = top_n

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        close_df = history.select(["symbol", "session_date", "adj_close"])
        returns = (
            close_df
            .pivot(index="session_date", columns="symbol", values="adj_close")
            .fillna(0.0)
            .with_columns(
                (pl.col("adj_close") / pl.col("adj_close").shift(self._window) - 1).alias("return")
            )
        )

        ranked_returns = returns.drop_nulls().select("symbol", "return").sort("return", descending=True)
        symbols = [row["symbol"] for row in ranked_returns.to_dicts()[: self._top_n]]

        if not symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(symbols)
        return Signal(
            information_available_at=stamp, weights={s: weight for s in symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
